const models={
 jordan:{title:'A new role. A deliberate identity transition.',outcome:'Preserve the work context while removing obsolete access.',nodes:[['HR + procurement','Resolve the person','Compare the hire record, contract date and stable identifier. Resolve duplicate records before choosing the identity that should continue.','Agreed identity match and effective date'],['Entra identity','Plan the transition','Inspect the chosen identity, user type and application dependencies. Establish what the approved conversion or migration must preserve.','Before-and-after identity records'],['Governance','Reconcile access','Compare groups, app roles and access packages with the employee role. Give overlap a named owner and an expiry decision.','Approved access changes'],['Applications','Test continuity','Use the employee browser profile to test the applications that matter. Check claims and application mappings where the identity changes.','Access to the intended work'],['Audit + sign-ins','Prove the handover','Correlate the identity decision, executed changes and sign-in result. A display-name change alone does not prove continuity.','Traceable changes and verified sign-in']]},
 sofia:{title:'From a hire signal to a useful first sign-in.',outcome:'Make identity, device and application access ready for the first shift.',nodes:[['HR source','Prepare the hire','Validate the start date, manager and role attributes that drive preparation.','Complete source record'],['Lifecycle workflow','Inspect preparation','Check workflow scope, trigger conditions and actual execution for the prepared hire.','Task results for the correct user'],['Authentication','Bootstrap securely','Use the prepared registration method and eligible device. Verify the intended user completes registration.','Registered method and sign-in evidence'],['Intune + apps','Make access useful','Inspect device targeting and required applications, then test the application Sofia needs.','Device and application readiness'],['Operations','Confirm readiness','Separate configured policies from observed enrollment, registration and app access. Assign exceptions to an owner.','A tested first-day journey']]},
 nadia:{title:'Remote onboarding across organization boundaries.',outcome:'Give outside talent useful access with a clear end date.',nodes:[['Contract source','Define the engagement','Establish the sponsor, manager, engagement dates and required work.','Approved time-bound engagement'],['Device provisioning','Prepare the device','Check eligible hardware, deployment profile and targeting. A remote desktop walkthrough does not prove an out-of-box deployment.','Verified device prerequisites'],['Authentication','Inspect the sign-in path','Verify the external authentication method and its scope. Rehearse sign-in on the prepared device.','Observed authentication result'],['Access governance','Bound the work','Compare package policies, approvers and assignment expiration with the contract date.','Scoped assignment and expiry'],['Expiry + evidence','Close the engagement','Verify the end-of-engagement execution and test the resulting access boundary.','Expiration evidence and exceptions']]},
 sam:{title:'One kiosk. A separate boundary for every shift.',outcome:'Keep work moving without carrying access into the next shift.',nodes:[['Shared device','Identify the session','Confirm kiosk mode, user context and applications. Distinguish device sign-in from application sign-in.','Known starting session'],['Federation','Follow authentication','Observe the redirect and authentication path. Verify the provider and returned result.','Traceable sign-in path'],['Session policies','Inspect the controls','Compare configured policy, report-only findings and actual prompts. Configuration alone does not prove enforcement.','Policy evaluation and observed behavior'],['Recovery','Rehearse an interruption','Walk through the prepared recovery scenario with the authorized support operator.','Recorded recovery outcome'],['Shift handover','Test the next person','Sign out and inspect the next session. Check application access and residual data independently.','Evidence of a clean handover']]},
 tom:{title:'Turn an expired contract into an accountable decision.',outcome:'Find stale access, decide the cleanup and verify execution.',nodes:[['Contract record','Find the end date','Compare the ended engagement with the current directory state. An end date alone does not remove access.','Source date and account state'],['Directory + apps','Establish remaining access','Inspect assignments and applications. Identify what remains and who owns it.','Access inventory'],['Workflow scope','Explain the gap','Inspect conditions, runs, execution history and failures. Establish why the expected control did not act.','Confirmed cause or explicit uncertainty'],['Access review','Make the decision','Present evidence to the reviewer. A recommendation is not an executed removal.','Approved cleanup scope'],['Audit + verification','Close the gap','Check executed changes and the application boundary. Record remaining access requiring separate action.','Verified removal and owned exceptions']]},
 kwame:{title:'A departure is complete when the evidence connects.',outcome:'Show what ended, what executed and what still needs an owner.',nodes:[['HR departure','Confirm the trigger','Verify the departure record, effective date and identity in scope.','Confirmed departure signal'],['Lifecycle workflow','Inspect execution','Find the relevant run and task results. Distinguish scheduled, failed and completed tasks.','Execution evidence'],['Directory controls','Verify account state','Check account state and intended session actions. Disablement and existing session termination are separate checks.','Account and session evidence'],['Application owners','Check entitlements','Inspect groups, app assignments and application-specific access. Track work outside the directory.','Removed access or owned exceptions'],['Evidence timeline','Make closure reviewable','Join source dates, workflow results, audit events and observed access.','Traceable offboarding outcome']]}
};
export function architectureView(p,m,selected=0){const model=models[p.id],index=Math.max(0,Math.min(4,selected)),n=model.nodes[index];return `<section class="architecture-studio" aria-label="${p.name} architecture"><div class="architecture-heading"><div><span class="studio-kicker">THE SYSTEM BEHIND THE STORY</span><h3>${model.title}</h3></div><span class="architecture-label">Illustrative deployment</span></div><ol class="architecture-track">${model.nodes.map((node,i)=>`<li><button type="button" data-action="architecture-node" data-value="${i}" aria-pressed="${i===index}" aria-controls="architecture-detail"><span class="architecture-index">0${i+1}</span><strong>${node[0]}</strong><small>${node[1]}</small></button></li>`).join('')}</ol><div class="architecture-detail" id="architecture-detail" aria-live="polite"><div><span class="studio-kicker">CONTROL 0${index+1} · ${n[0]}</span><h4>${n[1]}</h4><p>${n[2]}</p></div><aside><span>WHAT TO SHOW THE CLIENT</span><strong>${n[3]}</strong><p>Verify this in the prepared environment before describing it as a live result.</p></aside></div><div class="architecture-outcome"><span>BUSINESS OUTCOME</span><strong>${model.outcome}</strong></div><p class="architecture-context">This diagram explains the deployment path; it does not report live tenant state.</p></section>`;}
